{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Baclofen, a zwitterionic amino-acid drug, had absolute oral bioavailability of 85.8% at 15 mg in healthy volunteers, supporting high F for the query's amino-acid-like polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Levodopa, an amino acid with phenolic hydroxyls, showed absolute oral bioavailability of 71% in a controlled-release formulation and up to 99% for immediate release, supporting high F for the query's p-hydroxyphenyl amino-acid side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Desvenlafaxine, containing a phenolic hydroxyl and basic amine, had absolute oral bioavailability of about 80%, supporting high F for the query's p-hydroxyphenyl and amino functionalities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Chloramphenicol, an amide-containing small molecule, showed excellent oral bioavailability, supporting high F for the query's amide-bearing cephalosporin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Garenoxacin, a carboxylic-acid-containing drug, had absolute oral bioavailability of 92%, supporting high F for the query's carboxylic acid and ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Maraviroc had oral bioavailability of 33%, the lowest transferred value, still well above the 20% threshold, supporting high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence uniformly supports high absolute oral bioavailability: every evidence molecule has F above 20%, with most values between 33% and 99%. The query's amino-acid-like, phenolic, and carboxylic-acid features are consistent with well-absorbed oral drugs, and no affirmative evidence for F < 20% was found.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "No beta-lactam/cephalosporin analogue is present in the evidence set; transfer relies on chemically related oral drugs.",
    "Potential cephalosporin-specific instability or efflux is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

